# feature: F03
"""Feature-local helpers for lossless Ogg Opus compress and expand.

Ogg page construction follows RFC 3533. OpusHead / OpusTags fields follow
RFC 7845. Code-3 padding follows RFC 6716 section 3.2.5. These helpers
build suite inputs and read destination files; they are not a substitute
public entry.
"""

from __future__ import annotations

import base64
import re
import secrets
from pathlib import Path
from typing import Mapping, Sequence

from F01_helpers import (
    require_ok,
    require_stdout_text,
    run_product,
    unique_name,
)
from F02_helpers import (
    complete_packets,
    emit_ogg_page,
    first_complete_packet,
    is_opus_head,
    ogg_crc_page,
    parse_ogg_pages,
    replace_vorbis_comment,
    rewrite_first_page_packet,
)
from _harness import HarnessError, RunResult, Workspace, read_bytes

OPUS_MAX_PACKET = 61440
OPUS_TAGS_MAX = 120 * 1024 * 1024
OPUS_TAGS_MAGIC = b"OpusTags"
OPUS_HEAD_FAMILY0_LEN = 19
LONG_TIMEOUT = 600.0

# RFC 3533: 255 segments, each at most 255 bytes.
_OGG_MAXSEG = 255
_MAX_CONTINUE_BODY = _OGG_MAXSEG * _OGG_MAXSEG  # 65025; last lace is 255
_GRANULE_NONE = (1 << 64) - 1

_FIXTURE_DIR = Path(__file__).resolve().parent / "fixtures"
_KIND_FILES = {
    "silk": _FIXTURE_DIR / "opus_silk.opus",
    "celt": _FIXTURE_DIR / "opus_celt.opus",
    "hybrid": _FIXTURE_DIR / "opus_hybrid.opus",
}

# The feature mount ships this module and not the fixtures directory.
# These payloads are the suite-owned files. They are written to the
# lookup paths before the existing file load; the load itself stays.
_SHIPPED_FIXTURES = {
    'opus_silk.opus': '',
    'opus_celt.opus': '',
    'opus_hybrid.opus': '',
    'vorbis_ordinary_a.ogg': '',
    'vorbis_ordinary_b.ogg': '',
    'vorbis_ordinary_c.ogg': '',
}

_VORBIS_SCALE_NAMES = (
    "vorbis_ordinary_a.ogg",
    "vorbis_ordinary_b.ogg",
    "vorbis_ordinary_c.ogg",
)


def _ensure_shipped_fixture(path: Path) -> None:
    """Write a suite-owned fixture when that path is not a non-empty file.

    Callers still load *path*. A write failure raises; it is not treated
    as an absent fixture.
    """
    if path.is_file() and path.stat().st_size > 0:
        return
    payload = _SHIPPED_FIXTURES.get(path.name)
    if payload is None:
        return
    data = base64.b64decode(payload)
    if not data:
        raise HarnessError(f"shipped suite fixture is empty: {path.name}")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    except OSError as exc:
        raise HarnessError(
            f"cannot place suite fixture {path}: {exc}"
        ) from exc


def _place_shipped_fixtures() -> None:
    for name in _SHIPPED_FIXTURES:
        _ensure_shipped_fixture(_FIXTURE_DIR / name)


_place_shipped_fixtures()



def opus_head_fields(packet: bytes) -> tuple[int, int]:
    """Return (channel count, mapping family) from an RFC 7845 OpusHead packet."""
    if not is_opus_head(packet):
        raise HarnessError("packet is not OpusHead")
    if len(packet) < OPUS_HEAD_FAMILY0_LEN:
        raise HarnessError(
            "OpusHead shorter than the RFC 7845 family-0 19-byte header"
        )
    return packet[9], packet[18]


def rfc6716_config_kind(packet: bytes) -> str:
    """Map RFC 6716 TOC config to silk / hybrid / celt. Empty packet raises."""
    if not packet:
        raise HarnessError("empty Opus packet has no TOC")
    config = packet[0] >> 3
    if config <= 11:
        return "silk"
    if config <= 15:
        return "hybrid"
    if config <= 31:
        return "celt"
    raise HarnessError(f"TOC config {config} is outside RFC 6716 range 0–31")


def _opus_kind_bytes(kind: str) -> bytes:
    try:
        path = _KIND_FILES[kind]
    except KeyError as exc:
        raise HarnessError(f"unknown Opus fixture kind {kind!r}") from exc
    _ensure_shipped_fixture(path)
    if not path.is_file():
        raise HarnessError(f"suite fixture missing: {path}")
    try:
        data = read_bytes(path)
    except FileNotFoundError as exc:
        raise HarnessError(f"suite fixture missing: {path}") from exc
    if not data:
        raise HarnessError(f"suite fixture is empty: {path}")
    return data


def _prove_classified_opus(data: bytes, kind: str) -> None:
    packets = complete_packets(data)
    if len(packets) < 3:
        raise HarnessError(f"{kind} fixture has no audio packet")
    channels, family = opus_head_fields(packets[0])
    if family != 0:
        raise HarnessError(f"{kind} fixture mapping family is {family}, not 0")
    if not packets[1].startswith(OPUS_TAGS_MAGIC):
        raise HarnessError(f"{kind} fixture second packet is not OpusTags")
    got = rfc6716_config_kind(packets[2])
    if got != kind:
        raise HarnessError(
            f"{kind} fixture first audio TOC kind is {got!r}, not {kind!r}"
        )
    if kind == "silk" and channels != 1:
        raise HarnessError(f"silk fixture channel count is {channels}, not 1")
    if kind == "celt" and channels != 2:
        raise HarnessError(f"celt fixture channel count is {channels}, not 2")
    if kind == "hybrid" and channels not in (1, 2):
        raise HarnessError(
            f"hybrid fixture channel count is {channels}, not 1 or 2"
        )


def place_opus_classified(
    ws: Workspace, kind: str, *, suffix: str | None = ".opus"
) -> str:
    """Copy a suite-owned classified family-0 Opus file. Proof failure raises."""
    data = _opus_kind_bytes(kind)
    _prove_classified_opus(data, kind)
    rel = unique_name(f"opus-{kind}")
    if suffix:
        rel = f"{rel}{suffix}"
    if not suffix and (rel.endswith(".opus") or rel.endswith(".ogg")):
        raise HarnessError(f"unnamed Opus path still has a codec suffix: {rel}")
    ws.write(rel, data)
    return rel


def _first_audio_index(packets: Sequence[bytes]) -> int:
    if len(packets) < 3:
        raise HarnessError("Opus stream has no audio packet")
    if not is_opus_head(packets[0]):
        raise HarnessError("first packet is not OpusHead")
    if not packets[1].startswith(OPUS_TAGS_MAGIC):
        raise HarnessError("second packet is not OpusTags")
    return 2


def _complete_fits_one_page(n: int) -> bool:
    """True when *n* bytes can end a packet on one RFC 3533 page."""
    laces = 0
    remaining = n
    while remaining >= _OGG_MAXSEG:
        laces += 1
        remaining -= _OGG_MAXSEG
        if laces > _OGG_MAXSEG:
            return False
    laces += 1
    return laces <= _OGG_MAXSEG


def _packet_page_chunks(packet: bytes) -> list[tuple[bytes, bool]]:
    """Split *packet* into (chunk, continues) page bodies."""
    remaining = bytes(packet)
    chunks: list[tuple[bytes, bool]] = []
    while True:
        n = len(remaining)
        if _complete_fits_one_page(n):
            chunks.append((remaining, False))
            return chunks
        take = _MAX_CONTINUE_BODY
        if take >= n:
            take = ((n - 1) // _OGG_MAXSEG) * _OGG_MAXSEG
        if take <= 0 or take % _OGG_MAXSEG != 0:
            raise HarnessError(
                f"cannot page an Opus packet of length {len(packet)}"
            )
        chunks.append((remaining[:take], True))
        remaining = remaining[take:]


def _emit_spanned_packet(
    packet: bytes,
    *,
    serial: int,
    sequence: int,
    header_type: int,
    granule: int,
    eos: bool,
) -> tuple[bytes, int]:
    """Serialize *packet* as one or more Ogg pages. Returns (blob, next seq)."""
    chunks = _packet_page_chunks(packet)
    out = bytearray()
    seq = sequence
    for i, (chunk, continues) in enumerate(chunks):
        ht = header_type if i == 0 else 0
        if i > 0:
            ht |= 0x01
        last = i + 1 == len(chunks)
        if eos and last:
            ht |= 0x04
        page_granule = _GRANULE_NONE if continues else granule
        out += emit_ogg_page(
            header_type=ht,
            granule=page_granule,
            serial=serial,
            sequence=seq,
            packets=[chunk],
            tail=continues,
        )
        seq += 1
    return bytes(out), seq


def _rebuild_from_packets(data: bytes, packets: Sequence[bytes]) -> bytes:
    """Re-page *packets* with the original serial. Parse failure raises."""
    if not packets:
        raise HarnessError("no packets to rebuild")
    pages = parse_ogg_pages(data)
    serial = pages[0].serial
    out = bytearray()
    seq = 0
    n = len(packets)
    for i, pkt in enumerate(packets):
        ht = 0x02 if i == 0 else 0
        if i < 2:
            gran = 0
        elif i + 1 == n:
            gran = pages[-1].granule
        else:
            gran = (i - 1) * 960
        blob, seq = _emit_spanned_packet(
            pkt,
            serial=serial,
            sequence=seq,
            header_type=ht,
            granule=gran,
            eos=i + 1 == n,
        )
        out += blob
    rebuilt = bytes(out)
    got = complete_packets(rebuilt)
    if list(got) != list(packets):
        raise HarnessError("rebuilt bitstream packets do not match the source list")
    return rebuilt


def set_opus_head_family(data: bytes, family: int) -> bytes:
    """Rewrite OpusHead mapping family (byte 18) and CRC-repair the first page."""
    if not 0 <= family <= 255:
        raise HarnessError(f"mapping family {family} is not a byte")
    pkt = first_complete_packet(data)
    opus_head_fields(pkt)
    new = bytearray(pkt)
    new[18] = family
    return rewrite_first_page_packet(data, bytes(new))


def set_opus_head_channels(data: bytes, channels: int) -> bytes:
    """Rewrite OpusHead channel count (byte 9) and CRC-repair the first page."""
    if not 0 <= channels <= 255:
        raise HarnessError(f"channel count {channels} is not a byte")
    pkt = first_complete_packet(data)
    opus_head_fields(pkt)
    new = bytearray(pkt)
    new[9] = channels
    return rewrite_first_page_packet(data, bytes(new))


def _code3_pad(packet: bytes, target_len: int) -> bytes:
    """RFC 6716 code-3 (V=0, P=1, M=1) padding of a code-0 packet to *target_len*."""
    if not packet:
        raise HarnessError("empty audio packet")
    if (packet[0] & 3) != 0:
        raise HarnessError("audio packet is not RFC 6716 code 0")
    old = len(packet)
    if target_len < old + 2:
        raise HarnessError(
            f"target {target_len} cannot hold code-3 overhead from {old}"
        )
    extra = target_len - old - 2
    out = bytearray(target_len)
    out[0] = packet[0] | 3
    out[1] = 0x41
    nhdr = 2
    n255, rem = divmod(extra, 255)
    for _ in range(n255):
        out[nhdr] = 255
        nhdr += 1
    out[nhdr] = rem
    nhdr += 1
    frame = packet[1:]
    out[nhdr : nhdr + len(frame)] = frame
    return bytes(out)


def with_first_audio_code3_padding(data: bytes, target_len: int) -> bytes:
    """Pad the first audio packet to *target_len* with RFC 6716 code-3 padding."""
    packets = list(complete_packets(data))
    idx = _first_audio_index(packets)
    original = packets[idx]
    if (original[0] & 3) != 0:
        raise HarnessError("first audio packet is not RFC 6716 code 0")
    padded = _code3_pad(original, target_len)
    if padded == original:
        raise HarnessError("code-3 padding left the first audio packet unchanged")
    packets[idx] = padded
    rebuilt = _rebuild_from_packets(data, packets)
    if rebuilt == data:
        raise HarnessError("padded file equals the baseline")
    return rebuilt


def with_later_audio_code3_padding(data: bytes, target_len: int) -> bytes:
    """Pad a later complete code-0 audio packet to *target_len*."""
    packets = list(complete_packets(data))
    first = _first_audio_index(packets)
    idx = None
    for i in range(first + 1, len(packets)):
        pkt = packets[i]
        if pkt and (pkt[0] & 3) == 0:
            idx = i
            break
    if idx is None:
        raise HarnessError(
            "fixture has no later complete code-0 audio packet"
        )
    padded = _code3_pad(packets[idx], target_len)
    packets[idx] = padded
    rebuilt = _rebuild_from_packets(data, packets)
    if rebuilt == data:
        raise HarnessError("later-packet padded file equals the baseline")
    return rebuilt


def with_opus_head_padded(data: bytes, target_len: int) -> bytes:
    """Pad OpusHead with extra octets after the 19-byte family-0 header."""
    packets = list(complete_packets(data))
    pkt = packets[0]
    channels, family = opus_head_fields(pkt)
    if family != 0:
        raise HarnessError("padded OpusHead construction requires family 0")
    if target_len <= OPUS_HEAD_FAMILY0_LEN:
        raise HarnessError(
            f"OpusHead pad target {target_len} is not larger than 19"
        )
    padded = bytes(pkt[:OPUS_HEAD_FAMILY0_LEN]) + (
        b"\x00" * (target_len - OPUS_HEAD_FAMILY0_LEN)
    )
    if len(padded) != target_len:
        raise HarnessError("OpusHead pad length mismatch")
    del channels
    packets[0] = padded
    rebuilt = _rebuild_from_packets(data, packets)
    if rebuilt == data:
        raise HarnessError("padded OpusHead file equals the baseline")
    return rebuilt


def replace_opus_tags(
    data: bytes,
    *,
    vendor: bytes,
    fields: Sequence[bytes],
    packet_size: int | None = None,
) -> bytes:
    """Replace the OpusTags packet (RFC 7845, no Vorbis framing bit)."""
    packets = list(complete_packets(data))
    idx = next(
        (i for i, pkt in enumerate(packets) if pkt.startswith(OPUS_TAGS_MAGIC)),
        None,
    )
    if idx is None:
        raise HarnessError("Opus file has no OpusTags packet")
    original = packets[idx]
    payload = bytearray(OPUS_TAGS_MAGIC)
    payload += len(vendor).to_bytes(4, "little")
    payload += vendor
    payload += len(fields).to_bytes(4, "little")
    for field in fields:
        payload += len(field).to_bytes(4, "little")
        payload += field
    if packet_size is None:
        if len(payload) <= len(original):
            extra = len(original) - len(payload) + 1 + secrets.randbelow(32)
            payload.extend(b"\x00" * extra)
        if len(payload) <= len(original):
            raise HarnessError("constructed OpusTags packet is not strictly larger")
    else:
        if packet_size < len(payload):
            raise HarnessError(
                f"packet_size {packet_size} is smaller than the well-formed OpusTags"
            )
        payload.extend(b"\x00" * (packet_size - len(payload)))
        if len(payload) != packet_size:
            raise HarnessError("OpusTags packet_size padding mismatch")
    packets[idx] = bytes(payload)
    return _rebuild_from_packets(data, packets)


def with_ogg_version(data: bytes, version: int, *, page_index: int = 0) -> bytes:
    """Set RFC 3533 version on one page and CRC-repair that page only.

    Locates the page from a version-0 parse. Does not parse the mutated file.
    """
    if not 1 <= version <= 255:
        raise HarnessError(f"Ogg version {version} is not in 1–255")
    pages = parse_ogg_pages(data)
    if page_index >= len(pages):
        raise HarnessError(
            f"page index {page_index} out of range ({len(pages)} pages)"
        )
    if page_index > 0 and len(pages) < 2:
        raise HarnessError("file has no later page")
    page = pages[page_index]
    raw = bytearray(page.raw)
    raw[4] = version
    crc = ogg_crc_page(bytes(raw))
    raw[22:26] = int(crc).to_bytes(4, "little")
    return data[: page.offset] + bytes(raw) + data[page.offset + page.size :]


def dump_stdout(ws: Workspace, archive: str) -> str:
    """Run ``dump`` on *archive*. Non-zero exit or empty stdout raises/asserts."""
    result = run_product(ws, ["dump", archive])
    require_ok(result)
    return require_stdout_text(result)


def without_paths(text: str, paths: Sequence[str]) -> str:
    """Replace each caller-typed path (and its basename) with ``<path>``.

    Used so that a number or word inside a path cannot stand in for what a
    diagnostic itself states. Type errors raise.
    """
    if not isinstance(text, str):
        raise HarnessError(f"without_paths expected str, got {type(text)!r}")
    tokens: list[str] = []
    for raw in paths:
        piece = str(raw)
        if piece:
            tokens.append(piece)
            name = Path(piece).name
            if name and name != piece:
                tokens.append(name)
    remainder = text
    for tok in sorted(set(tokens), key=len, reverse=True):
        remainder = remainder.replace(tok, "<path>")
    return remainder


def states_decimal(text: str, value: int) -> bool:
    """True when *text* contains *value* as a whole decimal number."""
    if not isinstance(text, str):
        raise HarnessError(f"states_decimal expected str, got {type(text)!r}")
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise HarnessError(f"states_decimal expected a non-negative int, got {value!r}")
    return re.search(rf"(?<![0-9A-Za-z.]){value}(?![0-9])", text) is not None


# Contract `dump`: a ``codec: <codec>`` line names the codec the archive was
# made from (``opus`` or ``vorbis``); a ``stage: <stage>`` line carries the
# stored encoding stage. Leading whitespace is allowed on both.
_CODEC_LINE = re.compile(r"^\s*codec: (\S+)\s*$", re.MULTILINE)
_STORED_STAGE = re.compile(r"^\s*stage: (\d+)\s*$", re.MULTILINE)


def dump_codec(text: str) -> str:
    """The ``<codec>`` of dump stdout's single ``codec: <codec>`` line."""
    if not isinstance(text, str):
        raise HarnessError(f"dump_codec expected str, got {type(text)!r}")
    found = [m.group(1) for m in _CODEC_LINE.finditer(text)]
    assert len(found) == 1 and found[0] in ("opus", "vorbis"), (
        "dump standard output does not carry exactly one line "
        f"`codec: opus` or `codec: vorbis`; found={found!r} stdout={text!r}"
    )
    return found[0]


def dump_marks_opus(text: str) -> bool:
    """True when dump stdout's codec line is ``codec: opus``."""
    return dump_codec(text) == "opus"


def dump_stored_stage(text: str) -> int:
    """The decimal ``<stage>`` of dump stdout's ``stage: <stage>`` line."""
    if not isinstance(text, str):
        raise HarnessError(f"dump_stored_stage expected str, got {type(text)!r}")
    found = [int(m.group(1)) for m in _STORED_STAGE.finditer(text)]
    assert len(found) == 1, (
        "dump standard output does not carry exactly one stored-stage line "
        f"`stage: <stage>`; found={found!r} stdout={text!r}"
    )
    return found[0]


def run_product_long(
    ws: Workspace,
    args: Sequence[str],
    env_updates: Mapping[str, str | None] | None = None,
    *,
    timeout: float = LONG_TIMEOUT,
) -> RunResult:
    """Invoke the product with an explicit long timeout (120 MiB arms)."""
    print(
        f"[F03] long begin argv={list(args)!r} timeout={timeout}",
        flush=True,
    )
    result = ws.invoke(args, timeout=timeout, env_updates=env_updates)
    print(
        f"[F03] long argv={list(args)!r} timeout={timeout} exit={result.returncode} "
        f"stdout_len={len(result.stdout)} stderr_len={len(result.stderr)}",
        flush=True,
    )
    return result


def runtime_mapping_family() -> int:
    """Integer in 1–255."""
    return 1 + secrets.randbelow(255)


def runtime_family0_illegal_channels() -> int:
    """Integer in {0} ∪ {3…255}."""
    n = secrets.randbelow(254)
    return 0 if n == 0 else n + 2


def runtime_ogg_version() -> int:
    """Integer in 1–255."""
    return 1 + secrets.randbelow(255)


def runtime_code3_target_below_cap(packet_len: int) -> int:
    """Target strictly above code-3 overhead and strictly below 61,440."""
    overhead = packet_len + 2
    if overhead + 1 >= OPUS_MAX_PACKET:
        raise HarnessError(
            f"code-0 packet of {packet_len} bytes cannot form a below-cap pad"
        )
    span = OPUS_MAX_PACKET - overhead - 1
    return overhead + 1 + secrets.randbelow(span)


